const entrada = $input.first().json;
const body = entrada.body ?? entrada;

let clientes;

if (Array.isArray(body.clientes)) {
  clientes = body.clientes;
} else if (body.nome && body.email) {
  clientes = [body];
} else {
  throw new Error(
    "Não encontrei clientes nem um cliente individual na entrada."
  );
}

return clientes.map(cliente => ({
  json: cliente
}));

const entrada = $input.first().json;

const csv =
  typeof entrada.data === "string" ? entrada.data :
  typeof entrada.body === "string" ? entrada.body :
  typeof entrada === "string" ? entrada :
  null;

if (!csv) {
  throw new Error(
    "CSV não encontrado como texto. Confira a saída do HTTP Request."
  );
}

const linhas = csv.trim().split(/\r?\n/);

const cabecalhos = linhas[0]
  .replace(/^\uFEFF/, "")
  .split(",")
  .map(c => c.trim());

return linhas.slice(1)
  .filter(linha => linha.trim() !== "")
  .map(linha => {
    const valores = linha.split(",");
    const investimento = {};

    cabecalhos.forEach((coluna, i) => {
      investimento[coluna] = (valores[i] ?? "").trim();
    });

    return { json: investimento };
  });

const itens = $input.all();
const grupos = new Map();

for (const item of itens) {
  const d = item.json;

  // Adapte estes nomes se os campos de saída do Merge
  // estiverem diferentes.
  const nome = d.nome ?? d.cliente?.nome;
  const email = d.email ?? d.cliente?.email;
  const perfil = d.perfil;
  const produto = d.produto;
  const minimo = Number(d.minimo);

  const saldoBruto = d.saldo ?? d.saldo_cliente ?? d.balance;
  const saldo = typeof saldoBruto === "number"
    ? saldoBruto
    : Number(String(saldoBruto ?? "")
        .replace(/[R$\s]/g, "")
        .replace(/\./g, "")
        .replace(",", "."));

  if (!nome || !email || !perfil || !produto) continue;
  if (!Number.isFinite(saldo) || !Number.isFinite(minimo)) continue;
  if (saldo < minimo) continue;

  if (!grupos.has(email)) {
    grupos.set(email, {
      nome,
      email,
      perfil,
      saldo,
      investimentos: []
    });
  }

  grupos.get(email).investimentos.push({
    produto,
    minimo,
    rentabilidade: d.rentabilidade
  });
}

return [...grupos.values()].map(cliente => {
  const opcoes = cliente.investimentos
    .map(i => `${i.produto} (mínimo R$ ${i.minimo}; rentabilidade informada: ${i.rentabilidade})`)
    .join("; ");

  const mensagem =
    `Olá, ${cliente.nome}! Com base no seu perfil ${cliente.perfil} ` +
    `e no saldo informado de R$ ${cliente.saldo.toLocaleString("pt-BR", {minimumFractionDigits: 2})}, ` +
    `estas opções do nosso catálogo atendem ao valor mínimo: ${opcoes}. ` +
    `Estas são opções para fins informativos; avalie os riscos e as condições antes de investir.`;

  return {
    json: {
      ...cliente,
      mensagem
    }
  };
});
